mapper.update:
UPDATE plt_collection_task
SET status = #{update.status},
    technical_stage = #{update.technicalStage},
    external_task_id = #{update.externalTaskId},
    external_status = #{update.externalStatus},
    failure_category = #{update.failureCategory}
WHERE tenant_id = #{update.tenantId}
  AND platform_task_id = #{update.platformTaskId}
  AND technical_stage = #{update.expectedTechnicalStage}
  AND deleted = b'0'

UPDATE plt_collection_task
SET status = #{update.status},
    technical_stage = #{update.technicalStage},
    external_status = #{update.externalStatus},
    result_version = #{update.resultVersion},
    file_version_id = #{update.fileVersionId},
    quarantine_evidence_id = #{update.quarantineEvidenceId},
    failure_category = #{update.failureCategory},
    last_callback_sequence = #{update.lastCallbackSequence}
WHERE tenant_id = #{update.tenantId}
  AND platform_task_id = #{update.platformTaskId}
  AND status = #{update.expectedStatus}
  AND last_callback_sequence <=> #{update.expectedLastCallbackSequence}
  AND deleted = b'0'

UPDATE plt_collection_task
SET technical_stage = #{update.technicalStage}
WHERE tenant_id = #{update.tenantId}
  AND platform_task_id = #{update.platformTaskId}
  AND status = #{update.expectedStatus}
  AND last_callback_sequence <=> #{update.expectedLastCallbackSequence}
  AND deleted = b'0'

UPDATE plt_collection_task
SET status = #{update.status},
    consumed_result_version = #{update.consumedResultVersion}
WHERE tenant_id = #{update.tenantId}
  AND platform_task_id = #{update.platformTaskId}
  AND status = 'RESULT_AVAILABLE'
  AND result_version = #{update.expectedResultVersion}
  AND consumed_result_version IS NULL
  AND deleted = b'0'
